import{_ as s,C as n,o as l,c,a2 as r,j as e,E as d,a as t}from"./chunks/framework.Dx-TCpNt.js";const _=JSON.parse('{"title":"远程存储与备份","description":"本地磁盘是默认选择：KomaYomi 从 raw/ 读取图片，把标注写入 data/，把生成的文件写入 exports/。在此之上，服务器还支持通过 WebDAV 或挂载的 / SMB 网络共享来配置远程图片源和远程备份目标，相关设置位于数据工具 → 存储，保存在 data/storage…","frontmatter":{"description":"本地磁盘是默认选择：KomaYomi 从 raw/ 读取图片，把标注写入 data/，把生成的文件写入 exports/。在此之上，服务器还支持通过 WebDAV 或挂载的 / SMB 网络共享来配置远程图片源和远程备份目标，相关设置位于数据工具 → 存储，保存在 data/storage…"},"headers":[],"relativePath":"zh/remote-backup.md","filePath":"zh/remote-backup.md","lastUpdated":1794778149000}'),i={name:"zh/remote-backup.md"};function g(p,o,m,u,h,b){const a=n("Badge");return l(),c("div",null,[o[6]||(o[6]=r('<h1 id="远程存储与备份" tabindex="-1">远程存储与备份 <a class="header-anchor" href="#远程存储与备份" aria-label="Permalink to &quot;远程存储与备份&quot;">​</a></h1><h2 id="目前已有的能力" tabindex="-1">目前已有的能力 <a class="header-anchor" href="#目前已有的能力" aria-label="Permalink to &quot;目前已有的能力&quot;">​</a></h2><p>本地磁盘是默认选择：KomaYomi 从 <code>raw/</code> 读取图片，把标注写入 <code>data/</code>，把生成的文件写入 <code>exports/</code>。在此之上，服务器还支持通过 WebDAV 或挂载的 / SMB 网络共享来配置<strong>远程图片源</strong>和<strong>远程备份目标</strong>，相关设置位于<strong>数据工具 → 存储</strong>，保存在 <code>data/storage.json</code>（<code>schemaVersion: 1</code>）。</p><p>此外还有两道本地安全网，都便于迁移。</p><h3 id="远程图片源-webdav-网络驱动器" tabindex="-1">远程图片源（WebDAV / 网络驱动器） <a class="header-anchor" href="#远程图片源-webdav-网络驱动器" aria-label="Permalink to &quot;远程图片源（WebDAV / 网络驱动器）&quot;">​</a></h3><p>类型为 <code>webdav</code> 或 <code>network</code> 的存储目标可以设为 <code>rawSource</code>。</p><ul><li><strong>结构同步</strong> —— <strong>同步</strong> 会遍历远程目录树，把其中的文件夹镜像到 <code>raw/</code>，用零字节的占位文件表示（最多 20,000 个图片文件）。已有的图库扫描器和命名规则继续有效；占位文件标明了哪些页面存在。</li><li><strong>按需拉取</strong> —— 图片字节会在页面或缩略图首次打开时下载，而不是在同步时下载。已拉取的文件缓存在 <code>data/cache/remote/files/</code> 下，以“提供方 id + 相对路径”的 SHA-1 作为寻址键。</li><li><strong>LRU 缓存</strong> —— 缓存上限由 <code>cacheLimitMb</code> 控制（默认 <strong>512 MB</strong>）。每次写入后，服务器会按最近最少使用顺序清理文件，直到占用低于上限的 <strong>90%</strong>。缓存可以在存储界面中清空。</li><li><strong>离线时</strong> —— 已在缓存中的页面仍可阅读。未缓存的图片会返回 HTTP <strong>503</strong> 和错误码 <code>ERR_REMOTE_UNAVAILABLE</code>；缩略图拉取失败会返回 <strong>502</strong> <code>ERR_THUMB_FETCH_FAILED</code>。图库会继续列出这些页面，而不是卡住或静默丢弃。</li><li><strong>凭据</strong> —— 用户名保存在 <code>storage.json</code> 中；密码使用 <strong>AES-256-GCM</strong> 加密后保存在 <code>data/secrets.json.enc</code>，密钥是每次安装生成的 <code>data/.secret.key</code>（权限 <code>0600</code>）。API 只会报告 <code>hasSecret</code>，永远不会返回密码。这是可移植的兜底方案，而不是操作系统钥匙串；任何人把整个 data 文件夹连同 <code>.secret.key</code> 一起复制走，都能解密。</li><li><strong>WebDAV 细节</strong> —— Basic 认证，<code>PROPFIND</code> 用于列目录/查询状态，<code>GET</code> 用于读取，<code>PUT</code> 用于写入，请求超时 10 秒。只读目标仍可作为图片源使用，但会拒绝上传（<code>ERR_STORAGE_READONLY</code>）。</li></ul><h3 id="备份-zip" tabindex="-1">备份 ZIP <a class="header-anchor" href="#备份-zip" aria-label="Permalink to &quot;备份 ZIP&quot;">​</a></h3><ul><li>为 <code>data/</code> 创建 ZIP，每个条目都以 <code>data/</code> 为前缀，并带有 <code>data/.backup-meta.json</code> 标记文件。</li><li>排除缩略图缓存以及 <code>.tmp</code> / <code>.log</code> 文件。</li><li>文件写入 <code>exports/</code> 并提供下载。如果选择了备份目标，同一个 ZIP 还会被上传到该目标的 <code>backups/backup-&lt;timestamp&gt;.zip</code>。</li><li><strong>恢复前检查</strong> 会显示文件数、页面数、笔记数、卷、模板、预设、将被覆盖的文件数以及归档大小。</li><li><strong>恢复</strong> 会写入 <code>data/</code> 下的同名文件，但不会删除备份中不存在的页面。在发生任何覆盖之前，当前数据的快照会先写入 <code>exports/</code>，因此误点也可以撤销。</li></ul><h3 id="mnproj-项目包" tabindex="-1"><code>.mnproj</code> 项目包 <a class="header-anchor" href="#mnproj-项目包" aria-label="Permalink to &quot;`.mnproj` 项目包&quot;">​</a></h3><p>一个包含 <code>manifest.json</code>、页面 JSON、模板和预设的 ZIP，有两种模式：</p><ul><li><strong>引用（Reference）</strong> —— 记录图片路径和 SHA-1 哈希。体积小。如果图片被移动，导入时可以<strong>重新关联</strong>：先在选定文件夹中按哈希匹配，再按文件名匹配。</li><li><strong>打包（Packaged）</strong> —— 把去重后的图片嵌入 <code>assets/&lt;sha1&gt;.&lt;ext&gt;</code>。自包含、可移植，但体积大。</li></ul><p>导入行为：</p><ul><li>首先写入 <code>data/</code> 的快照。</li><li>原始项目包保留在 <code>data/backups/projects/</code> 下。</li><li>冲突可以按<strong>覆盖</strong>、<strong>合并</strong>或<strong>跳过</strong>处理。</li><li><strong>合并</strong>会在传入页面缺少分格/标注时保留已有的分格/标注，按 id 合并笔记，并且从不会删除已有笔记。</li></ul><p>清单字段和文件夹布局请参见<a href="/KomaYomi-docs/zh/data-format">数据格式</a>。</p><h2 id="推荐实践" tabindex="-1">推荐实践 <a class="header-anchor" href="#推荐实践" aria-label="Permalink to &quot;推荐实践&quot;">​</a></h2><ol><li><strong>把 <code>raw/</code> 放在大容量本地磁盘</strong>（或外接硬盘）上。它是数据的主体，并且已被 gitignore。</li><li><strong>定期用备份 ZIP 备份 <code>data/</code></strong>。它体积小——主要是 JSON——却包含你所有的工作成果。</li><li><strong>使用 <code>.mnproj</code> 引用模式</strong>在已经拥有相同图片的机器之间迁移标注。</li><li><strong>使用 <code>.mnproj</code> 打包模式</strong>把一个自包含的项目交给别人。</li><li><strong>保留一份 <code>exports/</code> 的副本</strong>，如果你想留存生成的学习文档；它已被 gitignore，可以重新生成。</li><li><strong>大图库可以放在 NAS 上并使用远程图片源</strong>；按需缓存让浏览保持流畅，同时避免在本地保留完整副本。</li></ol><h2 id="为什么不直接同步文件夹" tabindex="-1">为什么不直接同步文件夹？ <a class="header-anchor" href="#为什么不直接同步文件夹" aria-label="Permalink to &quot;为什么不直接同步文件夹？&quot;">​</a></h2><p>你可以把 <code>raw/</code>、<code>data/</code> 和 <code>exports/</code> 放在网络驱动器或同步文件夹中。应用不会锁定文件，但写入是原子性的（<code>.tmp</code> + 重命名），因此同步客户端不太可能看到写了一半的 JSON。避免同时从两台机器编辑同一页；后写入的会覆盖先写入的。</p><h2 id="计划中-仍然缺失" tabindex="-1">计划中：仍然缺失 <a class="header-anchor" href="#计划中-仍然缺失" aria-label="Permalink to &quot;计划中：仍然缺失&quot;">​</a></h2><p>以下内容<strong>尚未实现</strong>，列在这里是为了让预期明确：</p>',21)),e("ul",null,[e("li",null,[d(a,{type:"warning",text:"计划中"}),o[0]||(o[0]=t()),o[1]||(o[1]=e("strong",null,"定时备份",-1)),o[2]||(o[2]=t(" —— 自动周期性快照，可保存在本地或发送到配置的目标。",-1))]),e("li",null,[d(a,{type:"warning",text:"计划中"}),o[3]||(o[3]=t()),o[4]||(o[4]=e("strong",null,[e("code",null,"data/"),t(" 的带版本历史的远程同步")],-1)),o[5]||(o[5]=t(" —— WebDAV 目标目前只提供图片并接收备份 ZIP，并不会对标注数据库本身做版本管理。",-1))])]),o[7]||(o[7]=r('<p>在此之前，请把备份 ZIP、远程备份上传和 <code>.mnproj</code> 视为受支持的迁移机制。</p><h2 id="恢复检查清单" tabindex="-1">恢复检查清单 <a class="header-anchor" href="#恢复检查清单" aria-label="Permalink to &quot;恢复检查清单&quot;">​</a></h2><ol><li>点击 <strong>备份</strong>，确认 ZIP 出现在 <code>exports/</code> 中（或出现在选定的远程目标上）。</li><li>要恢复时：选择 <strong>检查</strong>，查看各项计数，然后选择 <strong>恢复</strong>。</li><li>恢复后重新加载图库；带有标注的页面会在侧边栏中显示徽章。</li><li>如果项目导入报告图片缺失，把<strong>重新关联目录</strong>指向包含这些图片的文件夹，然后用<strong>合并</strong>再次导入。</li></ol>',3))])}const x=s(i,[["render",g]]);export{_ as __pageData,x as default};
